{"command":"bash -lc 'set -euo pipefail
url_base=http://the-agent-company.com:8092
for path in \
  /remote.php/webdav/Documents/Food/drinks_survey.pdf \
  /Documents/Food/drinks_survey.pdf \
  /Documents/drinks_survey.pdf \
  /remote.php/webdav/Food/drinks_survey.pdf; do
  echo "Trying: $url_base$path";
  if curl -fsSL "$url_base$path" -o /workspace/drinks_survey.pdf; then
    echo "Downloaded from $url_base$path";
    break;
  fi;
  rm -f /workspace/drinks_survey.pdf || true;
done
if [ ! -f /workspace/drinks_survey.pdf ]; then
  echo "Failed to download PDF" >&2; exit 1; fi
ls -lh /workspace/drinks_survey.pdf && file /workspace/drinks_survey.pdf && md5sum /workspace/drinks_survey.pdf'"}

